<?php
$user=require_role('customer');
$o=fetch_one('SELECT * FROM orders WHERE order_no=? AND user_id=?',[$_GET['no']??'', $user['id']]);
if(!$o){http_response_code(404);exit(render_error(404,'Order not found.'));}
$items=flow_order_items((int)$o['id']);$pay=fetch_one('SELECT * FROM payments WHERE order_id=? ORDER BY id DESC LIMIT 1',[$o['id']]);
page_header('Order confirmation','orders'); ?>
<section class="card pad flow-sage flow-confirm row-between"><div><small>ORDER RECEIVED</small><h1>Thanks! Your order is confirmed.</h1><p>We’ve received your order and will start preparing your favorites.</p></div><div><small>ORDER NUMBER</small><h3>#<?= e($o['order_no']) ?></h3><small>Keep this for your records.</small></div></section>
<div class="cart-layout"><div class="stack"><section class="card pad"><div class="row-between"><h3>Your purchased items</h3><small><?= count($items) ?> products · <?= array_sum(array_column($items,'qty')) ?> items</small></div><?php flow_items($items); ?></section><section class="card pad"><small><?= $o['delivery_method']==='pickup'?'CAFÉ PICKUP':'DELIVERY' ?></small><h3><?= $o['delivery_method']==='pickup'?'Pickup at the café':'Standard delivery' ?></h3><p class="muted">Follow your order as it’s prepared.</p></section></div><aside class="stack"><section class="card pad flow-sage"><h3>Payment details</h3><?= status_badge(ucfirst($pay['status']??'pending')) ?><h4><?= ($pay['method']??'')==='cod'?'Cash on delivery':'Mock online payment' ?></h4><p class="small"><?= ($pay['status']??'')==='paid'?'Payment recorded.':'No payment has been taken. Pay when you receive your order.' ?></p><?php flow_totals($o); ?></section><a class="btn btn-block" href="<?= url('order',['no'=>$o['order_no']]) ?>">Track order →</a><a class="btn btn-ghost btn-block" href="<?= url('shop') ?>">Continue shopping</a></aside></div><?php page_footer();
